1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	import java.util.Locale;
5	import java.util.Set;
6	import java.util.regex.Pattern;
7	
8	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
9	
10	/**
11	 * Shared handling of the optional owner {@code email}: when present it must be a syntactically
12	 * valid address, and is stored (and later returned) lower-cased. Absent or blank email is accepted.
13	 *
14	 * <p>Used by both create ({@link ValidateOwnerFields}) and update ({@link ValidateOwner}) so the two
15	 * endpoints treat email identically.
16	 */
17	public final class OwnerEmail {
18	
19	    /**
20	     * Practical RFC-5322-ish syntactic check: a non-empty local part, an {@code @}, and a dotted
21	     * domain ending in a letter-only TLD of at least two characters. Rejects values with whitespace
22	     * or a missing {@code @}/domain (e.g. {@code not-an-email}).
23	     */
24	    private static final Pattern EMAIL = Pattern.compile(
25	        "^[\\w!#$%&'*+/=?`{|}~^-]+(?:\\.[\\w!#$%&'*+/=?`{|}~^-]+)*"
26	            + "@(?:[A-Za-z0-9](?:[A-Za-z0-9-]*[A-Za-z0-9])?\\.)+[A-Za-z]{2,}$");
27	
28	    /**
29	     * Disposable email domains that are not accepted: an email on one of these domains is rejected
30	     * (400) even though it is syntactically valid. Compared case-insensitively.
31	     */
32	    private static final Set<String> DISPOSABLE_DOMAINS = Set.of(
33	        "mailinator.com", "tempmail.com", "guerrillamail.com");
34	
35	    private OwnerEmail() {
36	    }
37	
38	    /**
39	     * Second-level labels of the known disposable domains (the label immediately before the final
40	     * TLD, e.g. {@code mailinator} for {@code mailinator.com}). Derived from
41	     * {@link #DISPOSABLE_DOMAINS} so the two stay in step.
42	     */
43	    private static final Set<String> DISPOSABLE_BASE_LABELS = DISPOSABLE_DOMAINS.stream()
44	        .map(OwnerEmail::secondLevelLabel)
45	        .collect(java.util.stream.Collectors.toUnmodifiableSet());
46	
47	    /**
48	     * The second-level label of a domain: the label immediately before the final dot (so
49	     * {@code mailinator.net} and {@code sub.mailinator.net} both yield {@code mailinator}). A
50	     * dot-less value is returned unchanged.
51	     */
52	    private static String secondLevelLabel(String domain) {
53	        String[] labels = domain.split("\\.");
54	        return labels.length >= 2 ? labels[labels.length - 2] : domain;
55	    }
56	
57	    /**
58	     * True when the email's domain is <em>disposable-adjacent</em>: it shares its second-level label
59	     * with one of the known disposable domains ({@link #DISPOSABLE_DOMAINS}) — for example a sibling
60	     * on a different TLD such as {@code mailinator.net}. Exact blocklisted domains are rejected at
61	     * validation (400) and so never reach a persisted owner, but they share the same base label and
62	     * are covered by this definition too. Absent, blank or unparseable email is not adjacent.
63	     */
64	    public static boolean isDisposableAdjacent(String email) {
65	        if (email == null || email.isBlank()) {
66	            return false;
67	        }
68	        String normalized = email.toLowerCase(Locale.ROOT);
69	        int at = normalized.lastIndexOf('@');
70	        if (at < 0 || at == normalized.length() - 1) {
71	            return false;
72	        }
73	        String domain = normalized.substring(at + 1);
74	        return DISPOSABLE_BASE_LABELS.contains(secondLevelLabel(domain));
75	    }
76	
77	    /**
78	     * Validates and normalizes the email on the request in place. When an email is present but not
79	     * syntactically valid, or its domain is on the disposable-domain blocklist, adds {@code "email"}
80	     * to {@code errors} (a 400). When valid, rewrites it lower-cased so persistence and the response
81	     * carry the canonical form. Absent/blank is a no-op.
82	     */
83	    static void normalize(OwnerFieldsDto request, List<String> errors) {
84	        String email = request.getEmail();
85	        if (email == null || email.isBlank()) {
86	            return;
87	        }
88	        if (!EMAIL.matcher(email).matches()) {
89	            errors.add("email");
90	            return;
91	        }
92	        String normalized = email.toLowerCase(Locale.ROOT);
93	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
94	        if (DISPOSABLE_DOMAINS.contains(domain)) {
95	            errors.add("email");
96	            return;
97	        }
98	        request.setEmail(normalized);
99	    }
100	}
